        var control = CreateEditorControl(value);

        // .NET 9: DropDownControl no longer accepts null; guard against it.
        if (control != null)
        {
            editorService.DropDownControl(control);
        }

        return value;
    }

    private Control CreateEditorControl(object value) => new ListBox();
}

